(window.webpackJsonp=window.webpackJsonp||[]).push([[57],{421:function(t,v,_){"use strict";_.r(v);var e=_(11),r=Object(e.a)({},(function(){var t=this,v=t._self._c;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("h3",{attrs:{id:"原文"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#原文"}},[t._v("#")]),t._v(" 原文")]),t._v(" "),v("p",[v("font",{attrs:{color:"#c00000",size:"5px"}},[v("center",[t._v("有道不处")])],1),t._v("\n夫唯兵者，不祥之器，物或恶之，故有道者不处。君子居则贵左，用兵则贵右。兵者不祥之器，非君子之器，不得已而用之，恬淡为上，胜而不美[1]。而美之者，是乐杀人[2]。夫乐杀人者，则不可以得志于天下矣。吉事尚左，凶事尚右。偏将军居左，上将军居右，言以丧礼处之。杀人之众，以哀悲莅之[3]，战胜，以丧礼处之。")],1),t._v(" "),v("br"),t._v(" "),v("Badge",{attrs:{text:"注释",type:"warning"}}),t._v(" "),v("p",[t._v("[1]美：这里是自以为了不起的意思。")]),t._v(" "),v("p",[t._v("[2]乐：以（杀人）作为快乐。")]),t._v(" "),v("p",[t._v("[3]莅：参加、到场的意思。")]),t._v(" "),v("Badge",{attrs:{text:"译文",type:"warning"}}),t._v(" "),v("p",[t._v("兵器啊，是不吉利的东西，谁都厌恶它，所以有“道”之人是不接近它的。君子平时的居处是以左边为尊贵的，而在用兵作战时则以右边为尊贵。兵器这种不吉利的东西，不是君子所用的啊，君子只有在迫不得已的情况下才去用它，而最好是不用兵器，淡然处之，即使作战胜利了，也不要自以为快意。那种为作战得胜而扬扬得意的人，是以杀人为快乐啊。以杀人为乐事的人，是不可以取得天下的。吉庆的事，以左边为尊贵；凶丧的事，以右边为尊贵。偏将军居于左边，而上将军居于右边，这也就是说，人们是将作战当作丧礼来看待的。战争中杀伤众多，应当以悲痛的心情去参加，战争胜利了，也要以丧礼的方式来对待。")]),t._v(" "),v("Badge",{attrs:{text:"阅读感悟",type:"warning"}}),t._v(" "),v("p",[t._v("万事万物有其存在道理，兵器是高级智慧维护自身存在的工具，顺应其使用规律即是顺应自然节律。若用其肆意破坏其他存在状态，便是熵增态。")]),t._v(" "),v("p",[t._v("自然界其他生物有利爪，有毒液等维护自身存在的特点。人类配置了大脑，用大脑造出兵器维护自身存在和其他动物异曲同工，但是为了心中贪婪肆意破坏生物平衡或者生态平衡，自然就会遭到反噬即熵增态")]),t._v(" "),v("br"),t._v(" "),v("hr"),t._v(" "),v("div",{staticClass:"center-container"},[v("p",[t._v("📢 "),v("code",[t._v("版权声明")]),t._v("：本文为原创文章，著作权归 "),v("code",[t._v("【赵敏】")]),t._v(" 所有。"),v("br"),t._v("\n个人学习、研究可自由转载，但必须注明出处；"),v("code",[t._v("商业用途必须获得书面授权")]),t._v("，侵权必究。")])]),v("br")],1)}),[],!1,null,null,null);v.default=r.exports}}]);